contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "len(stdin.strip().splitlines()) == N + 1",
      "description": "The input contains exactly N+1 lines: the first line is N, followed by N lines each containing a query."
    },
    {
      "id": "P2",
      "expression": "int(stdin.splitlines()[0]) == N",
      "description": "The first line of input is the integer N, representing the number of queries."
    },
    {
      "id": "P3",
      "expression": "all(1 <= int(parts[0]) <= 10**9 and 1 <= int(parts[1]) <= 10**9 for line in stdin.splitlines()[1:] for parts in [line.split()])",
      "description": "For every query line, the two integers i and j are within the range [1, 10^9]."
    },
    {
      "id": "P4",
      "expression": "1 <= N <= 10**5",
      "description": "The number of queries N is between 1 and 10^5 inclusive."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout.strip().splitlines()) == N",
      "description": "The output contains exactly N lines, one for each query."
    },
    {
